package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs in {@code POST /api/owners} after the owner entity is built and before it is saved, within
 * the create transaction. Stamps the built owner with the deterministic
 * {@link Household#id(String, String) household id} for its lastName and postcode. Because the id
 * is derived from those two fields alone, every owner in a household computes the same value
 * automatically — no backfill of existing members is needed and no opt-in is required.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(Household.id(owner.getLastName(), owner.getPostcode()));
    }
}
=== AssignOwnerHouseholdSize ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs in {@code POST /api/owners} after the owner's household id has been assigned and before
 * it is saved, within the create transaction. Records on the built owner how many members its
 * household holds once this create completes: the owners already sharing the same
 * {@link Owner#getHouseholdId() household id} plus the new owner itself. Because the new owner
 * has not yet been persisted, {@link OwnerRepository#findAll()} returns only the existing
 * members, so the {@code + 1} accounts for the owner being created. The household id is derived
 * deterministically from (lastName, postcode), so an owner alone in its household counts as one.
 */
public class AssignOwnerHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        long members = 1 + ownerRepository.findAll().stream()
                .filter(existing -> householdId.equals(existing.getHouseholdId()))
                .count(); // the owner being created, not yet persisted, plus existing members
        owner.setHouseholdSize((int) members);
    }
}
=== OwnerRegion ===
package org.springframework.samples.petclinic.util;

/**
 * The canonical region an owner belongs to: derived from the {@link PostcodeRange postcode range}
 * first, falling back to the fixed {@link CityRegion city-to-region table} when the postcode is
 * absent or in no known range, and {@link CityRegion#UNKNOWN} when neither resolves a region.
 *
 * <p>This is the single source of an owner's region, used both to build the region segment of the
 * {@link CustomerCode customer code} and to report the owner's locality.
 */
public final class OwnerRegion {

    private OwnerRegion() {
    }

    /** The region for the given {@code postcode} (preferred) or {@code city} (fallback). */
    public static String of(String postcode, String city) {
        String byPostcode = PostcodeRange.regionForPostcode(postcode);
        return byPostcode != null ? byPostcode : CityRegion.locality(city);
    }
}
=== PostcodeRange ===
package org.springframework.samples.petclinic.util;

import java.util.Map;

/**
 * Fixed region-to-postcode-range policy. A 4-digit postcode is valid for a city when it
 * falls within the inclusive range of the city's {@link CityRegion region} (NSW 2000-2099,
 * VIC 3000-3099, QLD 4000-4099). A city whose region is {@link CityRegion#UNKNOWN unknown}
 * accepts any 4-digit postcode.
 */
public final class PostcodeRange {

    /** The pinned region-to-inclusive-range table. */
    private static final Map<String, int[]> BY_REGION = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private PostcodeRange() {
    }

    /**
     * The region whose inclusive range contains {@code postcode}, or {@code null} when the
     * postcode is absent, non-numeric or in no known range. This is the reverse of the
     * {@link #BY_REGION region-to-range table} and the primary source of an owner's region.
     */
    public static String regionForPostcode(String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode.trim());
        } catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : BY_REGION.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * Whether the given 4-digit {@code postcode} is valid for {@code city}: within the
     * inclusive range of the city's region, or unconstrained when the region is unknown.
     * Assumes {@code postcode} is a 4-digit numeric string (as enforced by the DTO pattern).
     */
    public static boolean isValidForCity(String city, String postcode) {
        int[] range = BY_REGION.get(CityRegion.locality(city));
        if (range == null) {
            return true; // no known region -> any 4-digit postcode is accepted
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}

