43	        Set<String> invalid = new LinkedHashSet<>();
44	
45	        // Required fields must be present and non-blank.
46	        requiredFields(request).forEach((name, accessor) -> {
47	            String value = accessor.get();
48	            if (value == null || value.isBlank()) {
