1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Fixed region-to-postcode-range policy. A 4-digit postcode is valid for a city when it
7	 * falls within the inclusive range of the city's {@link CityRegion region} (NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099). A city whose region is {@link CityRegion#UNKNOWN unknown}
9	 * accepts any 4-digit postcode.
10	 */
11	public final class PostcodeRange {
12	
13	    /** The pinned region-to-inclusive-range table. */
14	    private static final Map<String, int[]> BY_REGION = Map.of(
15	            "NSW", new int[] {2000, 2099},
16	            "VIC", new int[] {3000, 3099},
17	            "QLD", new int[] {4000, 4099});
18	
19	    private PostcodeRange() {
20	    }
21	
22	    /**
23	     * The region whose inclusive range contains {@code postcode}, or {@code null} when the
24	     * postcode is absent, non-numeric or in no known range. This is the reverse of the
25	     * {@link #BY_REGION region-to-range table} and the primary source of an owner's region.
26	     */
27	    public static String regionForPostcode(String postcode) {
28	        if (postcode == null || postcode.isBlank()) {
29	            return null;
30	        }
31	        int value;
32	        try {
33	            value = Integer.parseInt(postcode.trim());
34	        } catch (NumberFormatException ex) {
35	            return null;
36	        }
37	        for (Map.Entry<String, int[]> entry : BY_REGION.entrySet()) {
38	            int[] range = entry.getValue();
39	            if (value >= range[0] && value <= range[1]) {
40	                return entry.getKey();
41	            }
42	        }
43	        return null;
44	    }
45	
46	    /**
47	     * Whether the given 4-digit {@code postcode} is valid for {@code city}: within the
48	     * inclusive range of the city's region, or unconstrained when the region is unknown.
49	     * Assumes {@code postcode} is a 4-digit numeric string (as enforced by the DTO pattern).
50	     */
51	    public static boolean isValidForCity(String city, String postcode) {
52	        int[] range = BY_REGION.get(CityRegion.locality(city));
53	        if (range == null) {
54	            return true; // no known region -> any 4-digit postcode is accepted
55	        }
56	        int value = Integer.parseInt(postcode);
57	        return value >= range[0] && value <= range[1];
58	    }
59	}
